import json

def encode_user(user):
    return json.dumps({'name': user['name']})

import json
from src.serializer import encode_user

def test_all_public_fields_are_encoded():
    result = json.loads(encode_user({'name': 'Ada', 'active': True}))
    assert result == {'name': 'Ada', 'active': True}

